{
  "rationale": "To allow clients in 10.0.1.0/24 to reach the web server network 10.0.2.0/24, a static route needs to be configured on r1 pointing to the next hop as 10.0.12.2. Additionally, to block access from clients to the management network 10.0.99.0/24 on r1, an access control rule should be added.",
  "static_routes": [
    {
      "node": "r1",
      "prefix": "10.0.2.0/24",
      "next_hop": "10.0.12.2"
    }
  ],
  "access_policy": [
    {
      "node": "r1",
      "src": "10.0.1.0/24",
      "dst": "10.0.99.0/24",
      "action": "deny"
    }
  ]
}
